[7044]={"#Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond. Find a way to speak with Celebras.","Get Celebrian Diamond - from Lord Vyletongue - Maraudon","Get Celebrian Rod - from Noxxion - Maraudon"},
